use std::{hint::black_box, sync::Arc, time::Instant};
use arrow::{array::*, datatypes::*};
use serde_json::json;
macro_rules! run {
    ($results:ident, $ty:ty, $native:ty, $array:ty) => {{
        let norm = |v: $native| if v == 0.0 { 0.0 } else if v.is_nan() { <$native>::NAN } else { v };
        for rows in [1, 32, 256, 8192, 65536] {
            for pattern in ["finite", "canonical_nan", "first", "last", "sparse", "dense", "nulls"] {
                let input = <$array>::from_iter((0..rows).map(|i| {
                    if pattern == "nulls" && i % 4 == 0 { return None; }
                    Some(if pattern == "canonical_nan" && i % 17 == 0 { <$native>::NAN }
                        else if (pattern == "first" && i == 0) || (pattern == "last" && i == rows-1)
                            || (pattern == "sparse" && i % 1024 == 900) || (pattern == "dense" && i % 2 == 0) { -0.0 }
                        else { (i % 97) as $native / 97.0 })
                }));
                let input: ArrayRef = Arc::new(input);
                let expected = input.as_primitive::<$ty>().unary::<_, $ty>(norm);
                for method in ["baseline", "clone", "copy", "all", "fold", "chunks"] {
                    let invoke = |input: ArrayRef| -> ArrayRef {
                        let a = input.as_primitive::<$ty>();
                        let unchanged = match method {
                            "clone" => true,
                            "all" => a.values().iter().all(|v| v.to_bits() == norm(*v).to_bits()),
                            "fold" => a.values().iter().fold(0, |diff, v| diff | (v.to_bits() ^ norm(*v).to_bits())) == 0,
                            "chunks" => a.values().chunks(64).all(|chunk| chunk.iter().fold(0, |diff, v| diff | (v.to_bits() ^ norm(*v).to_bits())) == 0),
                            _ => false,
                        };
                        if unchanged { input }
                        else if method == "copy" { Arc::new(a.unary::<_, $ty>(|v| v)) }
                        else { Arc::new(a.unary::<_, $ty>(norm)) }
                    };
                    let check = invoke(input.clone());
                    if method != "clone" && method != "copy" {
                        let actual = check.as_primitive::<$ty>();
                        assert_eq!(actual.nulls(), expected.nulls());
                        for (x,y) in actual.values().iter().zip(expected.values()) { assert_eq!(x.to_bits(),y.to_bits()); }
                    }
                    let repeats = (500_000 / rows).clamp(16, 10000);
                    let mut samples = vec![];
                    for i in 0..9 {
                        let start = Instant::now();
                        for _ in 0..repeats { black_box(invoke(black_box(input.clone()))); }
                        if i >= 2 { samples.push(start.elapsed().as_nanos() as f64 / repeats as f64); }
                    }
                    $results.push(json!({"type": stringify!($native), "rows": rows, "pattern": pattern, "method": method, "repetitions": repeats, "ns": samples}));
                }
            }
        }
    }};
}
fn main() {
    let mut results = vec![];
    run!(results, Float32Type, f32, Float32Array);
    run!(results, Float64Type, f64, Float64Array);
    std::fs::write(std::env::args().nth(1).unwrap(), serde_json::to_vec(&results).unwrap()).unwrap();
}

